function homeHeader(a){return `<header class="topbar home-topbar"><div class="home-wordmark"><span>IRENA <b>✧</b> REBORN</span><small>いれーな リボーン</small></div><div class="home-profile"><img src="${HOME_ART.hero}" alt="" width="36" height="36"><div><small>Lv.${n(a.level)}</small><strong>いれーな</strong></div></div><div class="home-wallet" aria-label="所持素材"><span>${uiIcon('star',16)}<b data-home-value="p">${n(a.p)}</b><small>P</small></span><span>${uiIcon('gem',16)}<b data-home-value="shards">${n(a.resShards)}</b><small>共鳴片</small></span></div><div class="home-header-tools">${button(uiIcon('book',21),'nav','archive','ghost home-archive-shortcut').replace('<button ','<button aria-label="実績アーカイブ" ')}${button(uiIcon('gear',21),'about','','ghost home-guide-shortcut').replace('<button ','<button aria-label="仕様・操作ガイド" ')}</div><div class="home-save ${saveError?'saved-error':''}">${saveError?'保存要確認':sandbox?'試験データ':'● AUTO SAVE'}</div></header>`;}
function homeGoal(a){
 const gates=[[5,'権能「堕天」'],[10,'権能「堕天王」'],[20,'権能「断罪」'],[50,'共鳴・深淵レイド'],[100,'境界への扉']];
 const next=gates.find(([floor])=>!a.cleared.includes(floor));
 if(next)return {title:`カイザー Lv.${next[0]} を撃破する`,value:a.cleared.filter(x=>x<=next[0]).length,total:next[0],label:'攻略階層',reward:next[1]};
 if(!a.flags.warp)return {title:'境界を越え、ステラを解放する',value:0,total:1,label:'境界への扉',reward:'ステラモード'};
 if(!a.flags.ex)return {title:'EXカイザーを撃破する',value:0,total:1,label:'EXカイザー',reward:'神域連戦'};
 if(!a.flags.stellaClear)return {title:'ステラ最終決戦をクリアする',value:0,total:1,label:'ステラ最終決戦',reward:'専用いれーな'};
 if(!a.flags.finalClear)return {title:'いれーな最終決戦をクリアする',value:0,total:1,label:'いれーな最終決戦',reward:'最終決戦のクリア記録'};
 if(a.awakening<5)return {title:'失われた神格を取り戻す',value:a.awakening,total:5,label:'神格覚醒',reward:AWAKENINGS[a.awakening+1]};
 return {title:'すべての戦いの記憶を集める',value:a.achieved.length,total:36,label:'実績',reward:'天星覇権 Lv.5'};
}
function homeCard({title,desc,icon,action,id,tone='gold',art=null,backgroundArt=null,unlocked=true,condition=''}){return `<section class="modecard home-card home-card-${tone} home-card-route-${id} ${art?'home-card-illustrated':''} ${backgroundArt?'home-card-backed':''} ${unlocked?'':'home-card-locked'}">${art||backgroundArt?`<img class="${art?'home-card-art':'home-card-background'}" src="${art||backgroundArt}" alt="${art?esc(title):''}" loading="lazy" decoding="async">`:`<span class="home-card-sigil">${uiIcon(icon,80)}</span>`}<div class="home-card-copy">${!art?uiIcon(icon,27):''}<h3>${title}</h3><p>${unlocked?desc:condition}</p></div>${button(`<span class="home-card-verb">${unlocked?'開く':'未解放'}</span><span class="home-card-arrow">›</span>`,action,id,'home-card-link',!unlocked).replace('<button ',`<button aria-label="${esc(title)}${unlocked?'':'：'+esc(condition)}" `)}</section>`;}
function home(a){const p=baseStats(a),goal=homeGoal(a),warpReady=a.flags.lv100&&!a.flags.warp,resuming=!!battle&&!battle.result;
 const challenge=button(`<span class="home-adventure-symbol">${uiIcon('star',29)}</span><span><strong>${resuming?'戦闘に戻る':warpReady?'境界の向こうへ':'冒険を続ける'}</strong><small>${resuming?'進行中の戦闘を再開':warpReady?'？？？？？':`カイザー Lv.${a.floor} に挑戦`}</small></span><span class="home-adventure-arrow">→</span>`,resuming?'nav':warpReady?'warp':'fight',resuming?'battle':warpReady?'':'normal','challenge-button home-adventure');
 const cards=[
 {title:'強化・装備',desc:'失われた力を、さらに強く',icon:'swords',action:'openupgrade',id:'powers',tone:'gold',backgroundArt:HOME_CARD_ART.powers},
 {title:'黒翼召喚',desc:'欠片を集め、新たな力へ',icon:'star',action:'openupgrade',id:'summon',tone:'violet',backgroundArt:HOME_CARD_ART.summon},
 {title:'深淵レイド',desc:'断片と育成資源を獲得',icon:'skull',action:'fight',id:'raid',tone:'blue',backgroundArt:HOME_CARD_ART.raid,unlocked:a.cleared.includes(50),condition:'通常Lv.50撃破で解放'},
