 {title:'ステラ最終決戦',desc:'不滅と再誕。星を越える戦い',icon:'star',action:'fight',id:'stella',tone:'blue',art:HOME_ART.stella,unlocked:a.flags.stella,condition:'Lv.100撃破後、境界を越える'},
 {title:'EX カイザー',desc:'三形態の終焉。最強の敵に挑む',icon:'crown',action:'fight',id:'ex',tone:'rose',art:HOME_ART.kaiser,unlocked:a.flags.stella,condition:'ステラ解放後に挑戦可能'}
