 return `<h1 class="home-screen-title">帰還の聖域</h1><section class="hero home-hero"><img class="hero-art key-art home-hero-art" src="${HOME_ART.hero}" alt="いれーな：金色の光と黒翼" fetchpriority="high" decoding="async"><div class="home-hero-copy"><p class="home-verse">もう一度、<br>世界を選び直す<span>終わりじゃない。<br>ここからが、私の物語。</span></p><div class="home-hero-title">IRENA REBORN<small>✧ ―― いれーな リボーン ―― ✧</small></div>${challenge}</div></section><section class="home-goal" aria-label="次の目標"><div class="home-goal-main"><div class="home-goal-kicker">✧ 次の目標</div><div class="home-goal-row"><h2>${goal.title}</h2><span data-home-value="goal">${goal.value}<small> / ${goal.total}</small></span></div><div class="progressline" role="progressbar" aria-label="${goal.label}" aria-valuemin="0" aria-valuemax="${goal.total}" aria-valuenow="${goal.value}"><span style="width:${Math.min(100,goal.value/goal.total*100)}%"></span></div></div><div class="home-goal-reward">${uiIcon('gem',27)}<span><small>次に目指す力</small><strong>${goal.reward}</strong></span></div></section><div class="home-modes home-card-grid">${cards.map(homeCard).join('')}</div><section class="home-archive archive"><div class="home-archive-title">${uiIcon('book',32)}<h2>アーカイブ</h2><p>実績と戦いの記憶を確認</p></div><div class="home-archive-count"><small>実績達成</small><strong class="number" data-home-value="achievements">${a.achieved.length}<small> / 36</small></strong></div>${button('実績を確認 →','nav','archive','ghost')}</section><details class="home-more"><summary>さらなる試練・神格覚醒</summary><div class="home-card-grid">${homeCard({title:'いれーな最終決戦',desc:'神化か、堕天か。新たな力の選択',icon:'star',action:'fight',id:'final',tone:'rose',unlocked:a.flags.final,condition:'ステラ最終決戦クリアで解放'})}${homeCard({title:'神域連戦',desc:'五柱の神々と、失われた神格',icon:'crown',action:'fight',id:'god',unlocked:a.flags.ex,condition:'EXカイザー撃破で解放'})}${homeCard({title:'神格覚醒',desc:`${AWAKENINGS[a.awakening]} / 第${a.awakening}段階`,icon:'star',action:'nav',id:'awakening'})}</div></details><details class="mobile-character home-character"><summary>いれーなのステータス・装備を確認</summary>${characterSummary(a,p)}</details><div class="row save-actions home-save-actions">${button('セーブ書き出し','export','','ghost small')}${button('セーブ読み込み','import','','ghost small')}${button('仕様・操作ガイド','about','','ghost small')}${button(sound?'音 ON':'音 OFF','sound','','ghost small')}</div>`;
}
function homeHubCard(icon,title,kicker,text,tabId){return `<section class="card modecard hub-card"><div class="hub-card-head"><span class="feature-icon">${uiIcon(icon,27)}</span><div><div class="tag">${kicker}</div><h3>${title}</h3></div></div><p class="small">${text}</p>${button(`開く ${uiIcon('arrow',16)}`,'openupgrade',tabId,'ghost')}</section>`;}
function raidView(a){const unlocked=a.cleared.includes(50);return `${heading('深淵レイド','階層の進行から離れ、深淵の守護者に挑む。','HIGH-LEVEL / RAID')}<section class="card raid-intro"><span class="feature-icon">${uiIcon('skull',36)}</span><h2>深淵の守護者</h2><p>${unlocked?'共鳴片を集め、さらなる力へ。':'通常カイザーLv.50を撃破すると解放されます。'}</p><div class="row"><span class="pill">勝利数 ${a.counts.raid}</span><span class="pill">実績まで ${Math.max(0,10-a.counts.raid)}勝</span><span class="pill">共鳴片＋25</span></div><div class="row">${button('レイドに挑戦する →','fight','raid','primary',!unlocked)}${button('育成を整える','openupgrade','powers','ghost')}</div></section>`;}

function modeCard(icon,title,desc,mode,unlocked,condition){return `<section class="card modecard"><div class="mode-symbol">${icon}</div><div class="tag">${unlocked?'UNLOCKED':'SEALED'}</div><h3>${title}</h3><p class="small">${unlocked?desc:condition}</p>${button(unlocked?'挑戦する →':'未解放','fight',mode,unlocked?'ghost':'',!unlocked)}</section>`;}
const UPGRADE_SECTIONS=[['powers','権能','深淵・黒翼・堕天・断罪など','権能の入手・強化・装備','violet'],['marks','刻印','刻印の装備・強化・管理','既存の刻印機能','red'],['resonance','権能共鳴','権能を組み合わせた共鳴権能','共鳴権能の作成・強化','gold'],['training','才能＆技','ステータス・才能・技の育成','既存の才能・技の育成','blue'],['summon','黒翼召喚','黒翼の召喚・育成・管理','既存の召喚機能','violet']];
function upgradeHero(a,detail=false){return `<header class="upgrade-hero"><img class="upgrade-hero-art" src="${UPGRADE_HERO}" alt=""><div class="upgrade-hero-copy"><span class="upgrade-crest" aria-hidden="true">✧</span><div><h1>${detail?'権能強化':'強化'}</h1><small>POWER UP</small><p>${detail?'強化する権能を選択してください':'強化したい項目を選択してください'}</p></div></div><div class="upgrade-wallet">権能ポイント <strong>✦ ${n(a.p)} P</strong></div></header>`;}
function upgrade(a){const section=UPGRADE_SECTIONS.find(x=>x[0]===tab);return `<div class="upgrade-ui">${upgradeHero(a,tab==='powers')}${tab==='overview'?`<section class="upgrade-category-list" aria-label="強化カテゴリ">${UPGRADE_SECTIONS.map(([id,title,desc,more,tone])=>`<button class="upgrade-category tone-${tone}" data-action="tab" data-id="${id}"><img src="${UPGRADE_ICONS[id]}" alt="" class="upgrade-category-icon"><span class="upgrade-category-copy"><strong>${title}</strong><span>${desc}</span><small>${more}</small></span><span class="upgrade-category-chevron" aria-hidden="true">›</span></button>`).join('')}</section><div class="upgrade-info">${uiIcon('book',26)}<span><strong>強化について</strong><small>項目を選択すると、既存の育成メニューに進みます。</small></span></div>`:`<section class="upgrade-subpage" aria-label="${section?.[1]||'育成'}">${tab==='powers'?powersView(a):`<h2 class="upgrade-subtitle">${section?.[1]||'育成'}</h2>${tab==='marks'?marksView(a):tab==='resonance'?resonanceView(a):tab==='training'?trainingView(a):summonView(a)}`}</section>`}</div>`;}
function powerStatus(a,p){
 const info=powerUpgradeInfo(a,p.id),selected=a.equipped.includes(p.id);
 const state=!info.lv?(p.id==='star'?'locked':'unowned'):info.max?'max':info.canUpgrade?'ready':'insufficient';
 const label={locked:'未解放',unowned:'未所持',max:'★ 最大レベル',ready:'↑ 強化可能',insufficient:'◇ 素材不足'}[state];
 return {...info,selected,state,label};
}
function powerDetails(a,p){
 const v=powerStatus(a,p),growth=lv=>Math.round((powerGrowth(lv)-1)*100),isStar=p.id==='star';
 const effect=lv=>`<p>${esc(p.effect)}</p>${!isStar?`<div class="detail-growth">育成補正：基礎HP・攻撃・防御・速度 <strong>＋${growth(lv)}%</strong></div>`:''}`;
 const next=v.max?'<p>★ 最大レベルに到達しています。</p>':!v.lv?`<p>${esc(p.source)}</p><small>${isStar?`実績 ${a.achieved.length} / ${ACHIEVEMENTS.length}`:'入手するとLv.1の固有効果が有効になります。'}</small><h3 class="unlock-effect-title">${isStar?'解放時の効果 · Lv.5':'入手時の効果 · Lv.1'}</h3>${effect(isStar?5:1)}`:effect(v.lv+1);
 return `<div class="upgrade-detail-modal"><header class="power-detail-heading"><img ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div><strong>${p.name}</strong><span>${v.lv?'Lv.'+v.lv+' / 5':'未解放・未所持'}</span><span class="power-state-badge badge-${v.state}">${v.label}</span>${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}</div></header><section class="upgrade-detail-section"><h3>現在の効果${v.lv?' · Lv.'+v.lv:''}</h3>${v.lv?effect(v.lv):'<p>未所持のため、まだ効果は発動しません。</p>'}</section><section class="upgrade-detail-section next-effect"><h3>${v.max?'強化完了':v.lv?'次レベルの効果 · Lv.'+(v.lv+1):'解放・入手条件'}</h3>${next}</section><dl class="power-detail-materials"><div><dt>強化に必要な欠片</dt><dd>${v.max?'— 最大レベル':!v.lv?'— 入手後に強化':n(v.cost)+' 個'}</dd></div><div><dt>所持欠片</dt><dd>${isStar?'— 実績報酬':n(v.have)+' 個'}</dd></div>${v.lv&&!v.max?`<div class="material-balance"><dt>${v.canUpgrade?'強化できます':'不足している欠片'}</dt><dd>${v.canUpgrade?'↑ 強化可能':n(v.cost-v.have)+' 個'}</dd></div>`:''}</dl><p class="small">装備枠は2つ。入手・装備・強化は一覧から操作できます。${!isStar?'固有効果はLv.1から有効で、Lv.2〜5は基礎能力の育成補正が上昇します。':''}</p></div>`;
}
function powersView(a){
 const ordered=['abyss','wing','fallen','king','judge','star'].map(id=>POWERS.find(p=>p.id===id));
 if(powerSort==='owned')ordered.sort((x,y)=>Number(!!a.powers[y.id])-Number(!!a.powers[x.id]));
 return `<div class="upgrade-powers-header"><h2>権能一覧</h2><button class="ghost" data-action="sortPowers" aria-label="権能一覧を並び替える">${powerSort==='owned'?'通常の順序':'所持優先に並び替え'}</button></div><div class="upgrade-power-grid">${ordered.map(p=>{
 const v=powerStatus(a,p),costText=!v.lv?(p.id==='star'?`実績 ${a.achieved.length}/${ACHIEVEMENTS.length}`:'入手 120 P'):v.max?'育成完了':`欠片 ${n(v.have)} / ${n(v.cost)}`;
 const action=v.lv?`${button(v.selected?'装備解除':'装備する','equipPower',p.id,'ghost equip-action')}${button(v.max?'MAX':'強化','upgradePower',p.id,'upgrade-action',!v.canUpgrade)}`:button(p.id==='star'?'解放条件':'120Pで入手',p.id==='star'?'powerDetails':'buyPower',p.id,'upgrade-action',p.id!=='star'&&a.p<120);
 return `<article class="upgrade-power-card state-${v.state} ${v.selected?'equipped':''}"><div class="upgrade-power-main"><img class="upgrade-power-art" ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div class="upgrade-power-identity"><h3>${p.name}</h3><p class="upgrade-power-level">${v.lv?'Lv.'+v.lv+' / 5':'未所持'}</p></div><button class="upgrade-power-detail" data-action="powerDetails" data-id="${p.id}" aria-label="${p.name}の詳細を見る">${uiIcon('search',19)}</button></div><div class="power-card-badges">${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}<span class="power-state-badge badge-${v.state}">${v.label}</span></div><div class="upgrade-power-meter" aria-label="強化レベル ${v.lv}/5"><span style="width:${v.lv*20}%"></span></div><div class="upgrade-power-cost">${costText}</div><div class="upgrade-power-actions">${action}</div></article>`;
 }).join('')}</div><div class="upgrade-info">${uiIcon('book',26)}<span><strong>権能の詳細</strong><small>虫眼鏡で現在・次レベルの効果と必要素材を比較できます。</small></span></div>`;
