 return `<section class="result ${victoryArt?'result-illustrated':''}">${victoryArt?`<img class="result-art" src="${SCENES.victory}" alt="通常戦闘の勝利イラスト">`:''}<div class="result-content"><div class="tag">${b.test?'TEST RESULT':'BATTLE RESULT'}</div><h2>${won?'VICTORY':'DEFEAT'}</h2><p class="small">${b.test?'試験戦闘のため本編報酬・実績には反映しません。':won?'失われた力を、またひとつ取り戻した。':'育成を整え、技と装備を組み替えて再挑戦できます。'}${b.mode==='god'&&!won?'<br>今回の仮獲得素材と連戦進行を破棄しました。':''}</p>${earned}${discoveries}${nextMilestone?`<p class="result-next">次の節目：カイザー Lv.${nextMilestone[0]} 撃破で ${nextMilestone[1]}</p>`:''}${r.unlocks?.includes('mystery')?button('？？？？？ — 境界を越える','warp','','primary full'):''}<div class="row" style="justify-content:center">${button('聖域に戻る','finish','','ghost')}${button(won&&b.mode==='normal'&&b.floor<100?'次の階層へ':b.mode==='god'&&a.gauntlet?'次の神へ':'再挑戦','retry','','primary')}</div></div></section>`;
