function archive(a){return `${heading('戦いの記憶','全36実績で、天星覇権 Lv.5を取り戻す。','ARCHIVE / ACHIEVEMENTS')}<div class="notice">達成 ${a.achieved.length}/36 / 受取 ${a.claimed.length}件。各実績60Pは手動で1回受取。条件の原本は未回収のため、提供された復元一覧を採用しています。</div><div class="grid triple">${[['A','火力','与ダメージ1.05 / 1.09 / 1.12倍'],['B','技巧','特殊1.08 / 1.12 / 1.15倍、必殺最大1.12倍'],['C','均衡','HP1.05 / HP防1.07 / 全能力1.12倍＋被ダメ0.92倍']].map(([cat,title,text])=>{const rank=badgeRank(a,cat),count=ACHIEVEMENTS.filter(x=>x.cat===cat&&a.achieved.includes(x.id)).length;return `<section class="card"><div class="row between"><span class="badge">${{A:'⚔',B:'✧',C:'⬡'}[cat]}</span><span class="tag">${count} / 12</span></div><h3>${title}の徽章 ${['—','I','II','III'][rank]}</h3><p class="small">3 / 5 / 8個で自動進化。${text}</p><div class="row">${button(a.badge===cat?'装備解除':'装備する','badge',cat,'ghost',!rank)}</div></section>`;}).join('')}</div>${['A','B','C'].map(cat=>`<div class="section-head"><h2>${{A:'A — 火力',B:'B — 技巧',C:'C — 均衡'}[cat]}</h2><span class="tag">12 RECORDS</span></div><div class="grid">${ACHIEVEMENTS.filter(x=>x.cat===cat).map(x=>`<section class="card achievement ${a.achieved.includes(x.id)?'':'locked'}"><div class="emblem">${a.achieved.includes(x.id)?'✧':'◇'}</div><div><h3>${x.name}</h3><p>${x.detail}</p></div>${button(a.claimed.includes(x.id)?'受取済':a.achieved.includes(x.id)?'60P 受取':'未達成','claim',x.id,'',!a.achieved.includes(x.id)||a.claimed.includes(x.id))}</section>`).join('')}</div>`).join('')}`;}
function awakeningView(a){return `${heading('失われた神格','新たな力ではない。かつての自分を、取り戻す。','DIVINE / REAWAKENING')}<div class="grid"><section class="card"><div class="tag">STAGE ${a.awakening} / 5</div><h2>${AWAKENINGS[a.awakening]}</h2><img class="awakening-art" src="${MEDIA.keyArt}" alt="ユーザー提供の共通キービジュアル（覚醒段階別ではありません）"><div class="levelsteps">${Array.from({length:5},(_,i)=>`<i class="${i<a.awakening?'on':''}"></i>`).join('')}</div><p class="small">各段階で通常基礎能力＋18%（補完）。共通キービジュアルを表示しています。5段階の専用絵とMP4は未提供です。</p></section><div class="stack"><section class="card"><h3>神格を取り戻す</h3><p class="small">共通神素材 ${a.godMaterials} / 神域の勲章 ${a.medals}<br>固有素材：${GODS.map((x,i)=>x+' '+a.godUnique[i]).join(' / ')}</p><p>${a.awakening<5?`次：${AWAKENINGS[a.awakening+1]}<br><span class="small">共通素材 ${(a.awakening+1)*5} ＋ ${GODS[a.awakening]}の固有素材1</span>`:'神格は完全に再生された。'}</p><div class="row">${button('手動で覚醒する','awaken','','primary',a.awakening>=5||a.godMaterials<(a.awakening+1)*5||a.godUnique[a.awakening]<1)}</div></section><section class="card"><h3>神域連戦</h3><p class="small">EX撃破後に解放。固定5連戦・各戦全回復。素材は全突破まで仮獲得。敗北・撤退で今回の進行と素材を失います。</p>${a.gauntlet?`<p>第${a.gauntlet.index+1}戦 / 仮素材 ${a.gauntlet.materials}</p>`:''}<div class="row">${button(a.gauntlet?'連戦を続ける':'神域へ挑戦','fight','god','ghost',!a.flags.ex)}</div></section><section class="card"><h3>第5段階の演出基盤</h3><p class="small">専用MP4の再生に対応。現在は10秒のCSS代替演出を使用します。元の覚醒ムービーではありません。</p>${button('代替演出をプレビュー','movie','','ghost')}</section></div></div>`;}
function lab(a){return `${campaignEntry(campaign,button)}${heading('境界の実験場','本編の保存データから独立した、戦闘検証空間。','EXPERIMENT / SANDBOX')}<div class="notice">ここで始めた戦闘はすべて試験扱いです。報酬、実績、通常の解放フラグを更新しません。</div><section class="card stack"><h2>戦闘パラメータ</h2><div class="selectline"><label>モード<select id="labmode"><option value="normal">通常いれーな</option><option value="ex">EXカイザー</option><option value="three-phase">EXカイザー・三相決戦【試作】</option><option value="stella">ステラ</option><option value="final">最終決戦いれーな</option></select></label><label>基礎攻撃倍率 <input id="labatk" type="number" value="1" min="0.1" max="20" step=".1"></label><label>基礎HP倍率 <input id="labhp" type="number" value="1" min="0.1" max="20" step=".1"></label></div><p class="small">全育成状態の試験キャラクターを使用。倍率はこの戦闘だけに適用します。三相決戦は黒翼＋堕天王の固定ビルドで開始。第二相から敵が硬化・重圧・回復を発動。破壊の権能・必殺で黒晶殻を解除、防御で重圧を解除、HP12%を回復して蓄勢を獲得。蓄勢は斬撃・破壊の権能を一回強化します。数値は実験用です。</p>${button('独立試験を開始','labstart','','primary')}</section><div class="section-head"><h2>計算仕様</h2></div><section class="card"><p class="small">基本ダメージ = max(1, 攻撃×技倍率 − 防御×(1−無視率)) × 最終補正 ＋ 現在HP追加。最低保証は最後に適用。低HP倍率は排他的。深淵は基礎値から毎ターン6%の線形減少、下限5%。<br>堕天によるHP倍率は内部の生命割合を維持するため、倍率切替だけでは回復しません。羽弾と断罪の乗算・追加は別枠です。</p></section>`;}
function dev(a){return `${heading('観測者の書架','全機能を検証するための、独立した試験用セーブ。','DEVELOPER / CONTROL')}<div class="notice">「全機能開放」は本編のコピーから試験データを作成します。テスト戦の勝利は実績・初回報酬を付与しません。本編へ戻ると元の進行をそのまま再開できます。天星覇権はここでも36実績条件を維持します。</div><section class="card"><h2>全機能開放</h2><p class="small">全階層、ステラ、EX、最終決戦、共鳴10種、刻印、育成・素材を開放。試験用セーブは独立キーに保存。</p><div class="row">${button(sandbox?'試験データを再作成':'全機能開放','enabledev','','primary')}${sandbox?button('本編へ戻る','exitdev','','ghost'):button('保存済み試験データを開く','resumedev','','ghost')}</div>${sandbox?`<div class="dev-buttons">${[['normal','通常Lv.100'],['ex','EXカイザー'],['stella','ステラ最終決戦'],['final','専用いれーな'],['god','神域連戦']].map(([id,title])=>button(title,'fight',id)).join('')}</div>`:''}</section><div class="section-head"><h2>セーブ管理</h2></div><section class="card"><div class="row">${button('JSONバックアップ','export','','ghost')}${button('JSONを読み込む','import','','ghost')}${button('タイトルへ','title','','ghost')}${button('本編を初期化','askReset','','danger')}</div><p class="footnote">保存キー：irena-reborn-v3 / 旧v1・v2キーも検索。未知の旧スキーマは推測して変換せず、エラーを表示します。</p></section>`;}
function tone(kind='hit'){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),g=audio.createGain();osc.connect(g);g.connect(audio.destination);osc.type=kind==='ultimate'?'sawtooth':'sine';osc.frequency.setValueAtTime(kind==='ultimate'?330:620,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(80,audio.currentTime+.18);g.gain.setValueAtTime(.05,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);osc.start();osc.stop(audio.currentTime+.25);}catch{sound=false;}}
function cinema(type,title,sub,done,duration=2400,art=null){
 if(combatAnimating)return;
