 const finish=()=>{if(completed)return;completed=true;clearTimeout(cinemaTimer);el.className='';el.innerHTML='';el.setAttribute('aria-hidden','true');try{done?.();}finally{combatAnimating=false;syncCombatBusy();}};
 combatAnimating=true;syncCombatBusy();
 el.className='active '+(type==='cut'?'cut':'');el.setAttribute('aria-hidden','false');
 el.innerHTML=`${type==='cut'?`<img src="${art||MEDIA.keyArt}" alt="${esc(title)}の演出画像">`:'<div class="tunnel"></div><div class="tunnel"></div><div class="tunnel"></div>'}<div class="cinema-copy"><h2>${title}</h2><p>${sub}</p></div><button id="skipCinema" type="button">スキップ</button>`;
 $('#skipCinema').onclick=finish;$('#skipCinema').focus({preventScroll:true});
 cinemaTimer=setTimeout(finish,matchMedia('(prefers-reduced-motion: reduce)').matches?50:duration);
}
// The alignment pause delays the actual turn (including enemy response) by 200 ms.
// Skip commits once immediately. None of these animations change combat calculations.
function syncCombatBusy(){
 const busy=combatAnimating||(typeof combatRecovering!=='undefined'&&combatRecovering);
 if(document.documentElement?.dataset)document.documentElement.dataset.combatBusy=String(busy);
 const app=$('#app');if(app)app.inert=busy;
 const controls=$('.battle-controls');controls?.setAttribute?.('aria-busy',String(busy));
}
function alignmentShift(id){
 const reason=available(battle,id);if(reason)throw Error(reason);if(combatAnimating)return;
 const fallen=id==='fallen',el=$('#cinema'),title=fallen?'堕天':'神化';let committed=false,finished=false;
 const commit=()=>{if(committed)return;committed=true;el.classList.add('revealed');doCombat(id);};
 const finish=()=>{if(finished)return;finished=true;clearTimeout(alignmentRevealTimer);clearTimeout(cinemaTimer);try{commit();}finally{el.className='';el.innerHTML='';el.setAttribute('aria-hidden','true');combatAnimating=false;syncCombatBusy();}};
 combatAnimating=true;syncCombatBusy();el.className='active alignment '+(fallen?'alignment-fallen':'alignment-divine');el.setAttribute('aria-hidden','false');
 el.innerHTML=`<div class="alignment-tint"></div><img class="alignment-crest" src="${fallen?SCENES.fallenCrest:SCENES.divineCrest}" alt="${title}の紋章"><img class="alignment-portrait" src="${fallen?PORTRAITS.fallen:PORTRAITS.divine}" alt="${title}の立ち絵"><div class="alignment-title">${title}</div><button id="skipCinema" type="button">スキップ</button>`;
 $('#skipCinema').onclick=finish;$('#skipCinema').focus?.({preventScroll:true});
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 alignmentRevealTimer=setTimeout(commit,reduced?0:200);
 cinemaTimer=setTimeout(finish,reduced?100:850);
}
const STRIKE_ACTIONS=new Set(['slash','feather','pierce','volley','power','ultimate','meteor','annihilate','genesis','ending']);
