function won(b){b.result='win';return b;}
test('normal attack deals damage and gauge +26',()=>{const b=plain();const before=b.enemy.hp;act(b,'slash',{rng:hit});assert.ok(b.enemy.hp<before);assert.equal(b.gauge,26);});
test('feather gauges +39 and CT rejects repeated cast',()=>{const b=weakEnemy(plain());act(b,'feather',{rng:hit});assert.equal(b.gauge,39);assert.throws(()=>act(b,'feather'));act(b,'slash',{rng:hit});assert.equal(available(b,'feather'),null);});
test('ultimate unavailable at 99 and consumes 100',()=>{const b=weakEnemy(plain());b.gauge=99;assert.throws(()=>act(b,'ultimate'));b.gauge=100;act(b,'ultimate',{rng:hit});assert.equal(b.gauge,0);assert.equal(b.used.ultimate,1);});
test('defense reduces incoming damage and gauges +18',()=>{const a=weakEnemy(plain()),b=clone(a);a.enemy.base.atk=b.enemy.base.atk=200;act(a,'slash',{rng:hit});act(b,'guard',{rng:hit});assert.ok(b.hp>a.hp);assert.equal(b.gauge,18);});
