for(const [ratio,mult] of [[1,1],[.5,2.4],[.25,3.1],[.1,3.8]])test(`fallen ratio ${ratio}: all stats x${mult} with stable health ratio`,()=>{const b=plain(['fallen']);b.hp=b.base.hp*ratio;const p=playerStats(b);for(const k of ['hp','atk','def','spd'])assert.equal(p[k],b.base[k]*mult);assert.equal(p.ratio,ratio);assert.ok(Math.abs(p.current/p.hp-ratio)<1e-10);});
test('fallen threshold does not multiply all tiers',()=>assert.equal(fallenMultiplier(.01),3.8));
