test('king HP and defense x1.2',()=>{const a=fresh(),base=baseStats({...a,equipped:[]});a.equipped=['king'];a.powers.king=1;const p=baseStats(a);assert.equal(p.hp,Math.round(base.hp*1.2));assert.equal(p.def,Math.round(base.def*1.2));});
